use std::fs;

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall: i32 = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?.trim().parse().map_err(|_| 1)?;
    let picked = rim::rim(wall, read::list("/app/daywell"));

    let _ = fs::remove_dir_all("/app/packbay/stage");
    let _ = fs::remove_dir_all("/app/packbay/latest");
    fs::create_dir_all("/app/packbay/stage").map_err(|_| 1)?;
    fs::create_dir_all("/app/packbay/latest").map_err(|_| 1)?;
    if picked.is_empty() {
        return Err(1);
    }

    let mut taken = 0;
    for (day, source) in &picked {
        let rows = read::nlines(source);
        taken += rows;
        fs::copy(source, format!("/app/packbay/stage/d{:08}.tbl", day)).map_err(|_| 1)?;
    }
    if taken == 0 {
        return Err(1);
    }

    soak::soak(&picked, "/app/packbay/latest")?;
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/ledger.json", format!("{{\"taken\":{}}}", taken)).map_err(|_| 1)?;
    Ok((picked, taken))
}
